'use strict';
const { clampInt } = require('./aerutil');

function pageOf(rows, page, size) {
  if (!Array.isArray(rows)) return null;

  const clampedSize = clampInt(size, 1, 100);
  const clampedPage = clampInt(page, 1, 1000);

  const start = (clampedPage - 1) * clampedSize;
  const end = start + clampedSize;

  return rows.slice(start, end);
}

module.exports = { pageOf };
```

