from aerelith.core.result import Result

def advance(task, to_state):
    legal_transitions = {
        'open': ['review', 'blocked'],
        'review': ['closed', 'blocked'],
        'closed': ['blocked'],
        'blocked': []
    }

    current_state = task.get('state')
    if current_state not in legal_transitions or to_state not in legal_transitions[current_state]:
        return Result(ok=False, value=None, err='E_STATE')

    new_task = task.copy()
    new_task['state'] = to_state
    return Result(ok=True, value=new_task, err=None)
```

