import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';
import { useAerTheme } from '../theme';

export function AerConfirmBar({ confirmLabel, onConfirm, onCancel }: { confirmLabel: string; onConfirm: () => void; onCancel: () => void }) {
  const theme = useAerTheme();
  return (
    <View style={{ flexDirection: 'row', justifyContent: 'space-between', padding: theme.space.lg }}>
      <TouchableOpacity onPress={onCancel}>
        <Text style={{ color: theme.color.muted }}>Cancel</Text>
